INSERT INTO movie (status, duration, language, name, pg_rating, synopsis, trailer, start_date, end_date, tmdb_id) VALUES
    (1, '2h 5min', 'English', 'The Electric State', 'PG-13', 'An orphaned teen hits the road with a mysterious robot to find her long-lost brother, teaming up with a smuggler and his wisecracking sidekick.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FThe%20Electric%20State%2FThe%20Electric%20State%20_%20Official%20Trailer%20_%20Netflix.mp4?alt=media&token=0ef98dc1-f58a-42f8-a5f0-80c309b94657','2025-01-01 00:00:00', '2025-07-01 00:00:00', '777443'),
    (1, '2h 19min', 'English', 'Anora', 'R', 'A young stripper from Brooklyn meets and impulsively marries the son of a Russian oligarch. Once the news reaches Russia, her fairy tale is threatened as his parents set out for New York to get the marriage annulled.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FAnora%2FAnora%20Trailer%20%231%20(2024).mp4?alt=media&token=7501a060-e050-4a4b-84ef-5f57febcb4d6', '2025-01-01 00:00:00', '2025-07-01 00:00:00', '1064213'),
    (1, '2h 17min', 'English', 'Mickey 17', 'R', 'Mickey 17, known as an "expendable," goes on a dangerous journey to colonize an ice planet.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FMickey%2017%2FMickey%2017%20_%20Official%20Trailer.mp4?alt=media&token=17da9c68-13da-435d-a8ea-77b15d1251b5', '2025-01-01 00:00:00', '2025-07-01 00:00:00', '696506'),
    (1, '2h 40min', 'English', 'Wicked', 'PG', 'Elphaba, a young woman ridiculed for her green skin, and Galinda, a popular girl, become friends at Shiz University in the Land of Oz. After an encounter with the Wonderful Wizard of Oz, their friendship reaches a crossroads.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FWicked%2FWicked%20-%20Official%20Trailer.mp4?alt=media&token=c8826661-d294-4681-8bea-291a1304f35d', '2025-01-01 00:00:00', '2025-07-01 00:00:00', '402431'),
    (1, '1h 33min', 'English', 'Black Bag', 'R', 'When intelligence agent Kathryn Woodhouse is suspected of betraying the nation, her husband - also a legendary agent - faces the ultimate test of whether to be loyal to his marriage, or his country.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FBlack%20Bag%2FBLACK%20BAG%20-%20Official%20Trailer%20%5BHD%5D%20-%20Only%20in%20Theaters%20March%2014.mp4?alt=media&token=389dd6ba-1875-45dc-99c8-46151801b52b', '2025-01-01 00:00:00', '2025-07-01 00:00:00', '1233575'),
    (1, '2h 50min', 'English', 'One Battle After Another', 'R', 'When their evil enemy resurfaces after 16 years, a group of ex-revolutionaries reunites to rescue one of their owns daughter.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FOne%20Battle%20After%20Another%2FOne%20Battle%20After%20Another%20%20-%20Official%20Trailer%20-%20Warner%20Bros.%20UK%20%26%20Ireland.mp4?alt=media&token=c5e5f445-ddb1-4712-9333-3090c27d7ece', '2025-01-01 00:00:00', '2025-07-01 00:00:00', '1054867'),
    (1, '1h 40min', 'English', 'Final Destination: Bloodlines', 'R', 'Plagued by a recurring violent nightmare, a college student returns home to find the one person who can break the cycle and save her family from the horrific fate that inevitably awaits them.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FFinal%20Destination%20Bloodlines%2FFinal%20Destination%20Bloodlines%20_%20Official%20Trailer.mp4?alt=media&token=f092b926-5dca-41c5-a287-504de61d6ff0', '2025-01-01 00:00:00', '2025-07-01 00:00:00', '574475'),
    (1, '1h 50min', 'English', 'Novocaine', 'R', 'When the girl of his dreams is kidnapped, a man incapable of feeling physical pain turns his rare condition into an unexpected advantage in the fight to rescue her.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FNovocaine%2FNovocaine%20_%20Official%20Trailer%20(2025%20Movie)%20-%20Jack%20Quaid%2C%20Amber%20Midthunder.mp4?alt=media&token=e8596874-8fb7-46c4-ac6d-fb61fdb2c010', '2025-01-01 00:00:00', '2025-07-01 00:00:00', '1195506'),
    (1, '1h 41min', 'English', 'A Minecraft Movie', 'PG', 'Four misfits are suddenly pulled through a mysterious portal into a bizarre, cubic wonderland that thrives on imagination. To get back home, theyll have to master this world while embarking on a quest with an unexpected, expert crafter.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FA%20Minecraft%20Movie%2FA%20Minecraft%20Movie%20_%20Final%20Trailer.mp4?alt=media&token=f16b807c-0cd9-4780-a3b3-b979839f52f4', '2025-01-01 00:00:00', '2025-07-01 00:00:00', '950387'),
    (1, '1h 50min', 'English', 'Holland', 'R', 'A woman''s picture-perfect life in quaint Holland, Michigan crumbles, when she and a friend uncover a twisted secret in their midst.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FHolland%2FHOLLAND%20-%20Official%20Trailer%20_%20Prime%20Video.mp4?alt=media&token=6597b886-569b-4a3c-969c-8e60faa71a31', '2025-01-01 00:00:00', '2025-07-01 00:00:00', '257094'),
    (1, '1h 56min', 'English', 'A Working Man', 'R', 'Levon Cade left his profession behind to work construction and be a good dad to his daughter. But when a local girl vanishes, he''s asked to return to the skills that made him a mythic figure in the shadowy world of counter-terrorism.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FA%20Working%20Man%2FA%20Working%20Man%20_%20Official%20Trailer.mp4?alt=media&token=18335631-77fb-4b24-ab89-53660ec890f3', '2025-01-01 00:00:00', '2025-07-01 00:00:00', '1197306'),
    (1, '1h 58min', 'English', 'Mufasa: The Lion King', 'PG', 'Mufasa, a cub lost and alone, meets a sympathetic lion named Taka, the heir to a royal bloodline. The chance meeting sets in motion an expansive journey of a group of misfits searching for their destiny.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FMufasa%3A%20The%20Lion%20King%2FMufasa_%20The%20Lion%20King%20_%20Official%20Trailer.mp4?alt=media&token=dabf4fdd-0ef7-4af5-ac37-5f9a352d7d34', '2025-07-01 00:00:00', '2026-01-01 00:00:00', '762509'),
    (1, '1h 38min', 'English', 'The Monkey', 'R', 'When twin brothers Bill and Hal find their father''s old monkey toy in the attic, a series of gruesome deaths start. The siblings decide to throw the toy away and move on with their lives, growing apart over the years.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FThe%20Monkey%2FTHE%20MONKEY%20-%20Official%20Redband%20Trailer%20-%20%20In%20Theaters%20February%2021.mp4?alt=media&token=f98e4171-0ecb-4ac8-825c-5894556ae4a3', '2025-07-01 00:00:00', '2026-01-01 00:00:00', '1124620'),
    (1, '1h 47min', 'English', 'Death of a Unicorn', 'R', 'Father-Daughter duo Elliott and Ridley hit a unicorn with their car and bring it to the wilderness retreat of a mega-wealthy pharmaceutical CEO.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FDeath%20of%20a%20Unicorn%2FDeath%20Of%20A%20Unicorn%20_%20Official%20Trailer%20HD%20_%20A24.mp4?alt=media&token=93fb206f-6257-42db-a80f-2d0aaf13ee32', '2025-07-01 00:00:00', '2026-01-01 00:00:00', '1153714'),
    (1, '2h 3min', 'English', 'The Alto Knights', 'R', 'Two of New York City''s most notorious organized crime bosses vie for control of the city''s streets. Once best friends, petty jealousies and a series of betrayals set them on a deadly collision course.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FThe%20Alto%20Knights%2FThe%20Alto%20Knights%20_%20Official%20Trailer.mp4?alt=media&token=b9ab06a0-8ca6-4865-ab50-b13423337d36', '2025-07-01 00:00:00', '2026-01-01 00:00:00', '1013601'),
    (1, '1h 40min', 'English', 'Moana 2', 'PG', 'After receiving an unexpected call from her wayfinding ancestors, Moana must journey to the far seas of Oceania and into dangerous, long-lost waters for an adventure unlike anything she''s ever faced.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FMoana%202%2FMoana%202%20_%20Official%20Trailer.mp4?alt=media&token=a446ba63-fd9e-4eb1-a383-579c1046a574', '2025-07-01 00:00:00', '2026-01-01 00:00:00', '1241982'),
    (1, '2h 21min', 'English', 'A Complete Unkown', 'R', 'In 1961, an unknown 19-year-old Bob Dylan arrives in New York City with his guitar and forges relationships with musical icons on his meteoric rise, culminating in a groundbreaking performance that reverberates around the world.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FA%20Complete%20Unkown%2FA%20COMPLETE%20UNKNOWN%20_%20Official%20Trailer%20_%20Searchlight%20Pictures.mp4?alt=media&token=bc312cc1-1dbb-4815-9e06-cb2726e650be', '2025-07-01 00:00:00', '2026-01-01 00:00:00', '661539'),
    (1, '1h 33min', 'English', 'Last Breath', 'PG-13', 'A true story that follows seasoned deep-sea divers as they battle the raging elements to rescue their crew mate trapped hundreds of feet below the ocean''s surface.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FLast%20Breath%2FLast%20Breath%20-%20Official%20Trailer%20%5BHD%5D%20-%20Only%20in%20Theaters%20February%2028.mp4?alt=media&token=ee62308c-37ba-4561-970e-01a7d6ac50e5', '2025-07-01 00:00:00', '2026-01-01 00:00:00', '972533'),
    (1, '2h 7min', 'English', 'The Gorge', 'PG-13', 'Two highly-trained operatives become close after being sent to protect opposite sides of a mysterious gorge. When an evil emerges, they must work together to survive what lies within.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FThe%20Gorge%2FThe%20Gorge%20%E2%80%94%20Official%20Trailer%20_%20Apple%20TV%2B.mp4?alt=media&token=97cd456a-17f6-4e22-992d-3788e2064e04', '2025-07-01 00:00:00', '2026-01-01 00:00:00', '950396'),
    (1, '2h 21min', 'English', 'The Substance', 'R', 'A fading celebrity takes a black-market drug: a cell-replicating substance that temporarily creates a younger, better version of herself.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FThe%20Substance%2FTHE%20SUBSTANCE%20_%20Official%20Trailer%20_%20In%20Theaters%20%26%20On%20MUBI%20Now.mp4?alt=media&token=7d3baed5-5cc3-42bf-9518-7d6453a0d360', '2025-07-01 00:00:00', '2026-01-01 00:00:00', '933260'),
    (1, '1h 37min', 'English', 'Companion', 'R', 'A weekend getaway with friends at a remote cabin turns into chaos after it''s revealed that one of the guests is not what they seem.', 'https://firebasestorage.googleapis.com/v0/b/cinebhapp-storage.firebasestorage.app/o/trailers%2FCompanion%2FCompanion%20_%20Official%20Trailer.mp4?alt=media&token=83a9ca0e-4804-4c83-bfdb-c65c34c93dc1', '2025-07-01 00:00:00', '2026-01-01 00:00:00', '1084199');
